from docich.hanjuku_speedrun.hanjuku.judgment import battle as judgment


def test_cards_are_unusable_only_in_defense():
    assert judgment._card_usable_here({'side': 'defense'}) is False
    assert judgment._card_usable_here({'side': 'attack'}) is True
    assert judgment._card_usable_here({}) is True
    assert judgment._card_usable_here(None) is True


def _defense_battle(**changes):
    cur = {'side': 'defense', 'castle': 'ウラノポリス', 'ally': 'ヘルメス',
           'enemy': 'エシャロット', 'ally_hp': 80, 'enemy_hp': 120,
           'enemy_summon_observed': True, 'summon_egg_unavailable': True,
           'planned_cards': ['バグストーム']}
    cur.update(changes)
    return cur


def test_a_defense_summon_with_no_egg_takes_okunote_even_with_carried_cards():
    mem = {'chapter': 2}
    window = judgment._defender_summon_preempt(mem, _defense_battle())
    assert window is not None and window['due'] is True
    assert window['reason'] == 'enemy_summon_present'


def test_an_attack_summon_with_a_carried_card_keeps_the_card():
    cur = {'side': 'attack', 'castle': 'ウラノポリス', 'ally': 'ヘルメス',
           'enemy': 'エシャロット', 'ally_hp': 80, 'enemy_hp': 120,
           'enemy_summon_observed': True, 'summon_egg_unavailable': True,
           'planned_cards': ['バグストーム']}
    assert judgment._defender_summon_preempt({'chapter': 2}, cur) is None


def test_a_defense_without_a_summon_keeps_melee():
    mem = {'chapter': 2}
    cur = _defense_battle(enemy_summon_observed=False)
    assert judgment._defender_summon_preempt(mem, cur) is None


def test_a_defense_summon_without_okunote_is_flagged_from_the_battle_result():
    from docich.hanjuku_speedrun.hanjuku.flows import battle as battle_flow

    cur = {'side': 'defense', 'ally': 'ヘルメス', 'enemy': 'エシャロット',
           'enemy_summon_observed': True, 'summon_egg_unavailable': True,
           'okunote_summon_preempt': {'opens': 1}}
    assert battle_flow._defense_summon_without_okunote({}, cur) is True

    used = {**cur, 'okunote_summon_preempt': {'opens': 1, 'selected': True}}
    assert battle_flow._defense_summon_without_okunote({}, used) is False

    egg_present = {**cur, 'summon_egg_unavailable': False}
    assert battle_flow._defense_summon_without_okunote({'egg_uses': {'ヘルメス': 2}},
                                                       egg_present) is False

    attack = {**cur, 'side': 'attack'}
    assert battle_flow._defense_summon_without_okunote({}, attack) is False


def test_the_battle_result_evidence_files_one_issue(monkeypatch):
    from docich.hanjuku_speedrun.hanjuku import fault_issue

    calls = []
    monkeypatch.setattr(fault_issue, 'note_fault', lambda *a, **kw: calls.append(kw) or {'status': 'ok'})
    record = {'decision': 'battle_result', 'ally': 'ヘルメス', 'enemy': 'エシャロット',
              'observed_metric': {'defense_summon_no_okunote': True}}
    fault_issue.note_decision_faults('/tmp/unused-runtime', [record])
    assert [c['signature'] for c in calls] == ['defense_summon_no_okunote']
